transfer.sketch:
nodules = detect(scan)                     -- rows: id, slice, cx, cy, d_mm, score
keep = sortBy(nodules, -score)[0:15]        -- code filters; ids unchanged
sheet(keep, views: [window(crop, "lung"), window(crop, "soft")],
      cell: 64 px, zoom: 3, stretch: "fixed").look("top 15")

byId = { i.id: i for s in deliveredSheets(session) for i in s.items }
for i in answer.nodules:
  if i not in byId: return refuse(E_UNKNOWN_ID, i, valid: keys(byId), hint: "cite ids from the last sheet")
labels = [byId[i] for i in answer.nodules]  -- exact slice, cx, cy, diameter
